INSERT INTO `stages` (`id`, `code`, `title`, `description`, `theme_key`, `accent_color`, `sort_order`, `created_at`) VALUES
(1, 'stage-1', 'A1 Beginner Basics', 'Xây dựng nền tảng từ vựng và câu giao tiếp căn bản hàng ngày.', 'forest', '#3E9B5F', 1, '2026-10-27 08:28:12'),
(2, 'stage-2', 'A2 Elementary Communication', 'Giao tiếp trong các tình huống quen thuộc và mua sắm, đi lại.', 'river', '#2E9CC4', 2, '2026-10-27 08:28:12'),
(3, 'stage-3', 'B1 Intermediate Skills', 'Tự tin xử lý tình huống khi du lịch, học tập và phỏng vấn.', 'autumn', '#D97706', 3, '2026-10-27 08:28:12'),
(4, 'stage-4', 'B2 Upper-Intermediate Business', 'Làm chủ tiếng Anh công sở, cuộc họp, email và đàm phán.', 'alpine', '#2E7DA8', 4, '2026-10-27 08:28:12'),
(5, 'stage-5', 'C1 Advanced Fluency', 'Bày tỏ quan điểm sâu sắc, kể chuyện và diễn đạt ý tưởng phức tạp.', 'coast', '#2A9D8F', 5, '2026-10-27 08:28:12'),
(6, 'stage-6', 'C2 Mastery & Proficiency', 'Thành thạo như người bản xứ, làm chủ thành ngữ và văn phong học thuật.', 'sakura', '#D65A86', 6, '2026-10-27 08:28:12');
