INSERT INTO `video_lessons` (`id`, `code`, `title`, `description`, `topic`, `cefr_level`, `provider`, `video_url`, `thumbnail_url`, `duration_seconds`, `xp_reward`, `sort_order`, `owner_user_id`, `subtitle_en`, `subtitle_vi`, `created_at`) VALUES
(66, 'demo-small-talk', 'Small Talk at Work — Hỏi thăm đồng nghiệp', 'Một cuộc trò chuyện ngắn ở công sở: hỏi thăm công việc mới, đồng nghiệp và cách giữ chuỗi ngày học.', 'Giao tiếp công sở', 'A2', 'youtube', 'https://www.youtube.com/watch?v=ry9SYnV3svc', 'https://i.ytimg.com/vi_webp/ry9SYnV3svc/maxresdefault.webp', 133, 25, 1, NULL, 'So what''s new mark how is your new job going to be honest i can''t complain i really love the company that i am', NULL, '2026-11-08 22:43:10'),
(67, 'demo-trip', 'A Trip to Remember — Kể lại chuyến đi', 'Luyện thì quá khứ đơn qua câu chuyện về thời tiết, món ăn và một chuyến đi đáng nhớ.', 'Du lịch', 'A2', 'youtube', 'https://www.youtube.com/watch?v=mngiqrT44Pk', 'https://i.ytimg.com/vi_webp/mngiqrT44Pk/maxresdefault.webp', 75, 25, 2, NULL, 'How was your trip it was really fun how was the weather the weather was', NULL, '2026-11-07 22:43:10'),
(68, 'demo-viva', 'Viva La Vida — Luyện nghe qua bài hát', 'Nghe từng câu trong bản hit của Coldplay và gõ lại lời bài hát.', 'Âm nhạc', 'B1', 'youtube', 'https://www.youtube.com/watch?v=dvgZkm1xWPE', 'https://i.ytimg.com/vi_webp/dvgZkm1xWPE/maxresdefault.webp', 242, 20, 3, NULL, 'I used to rule the world Seas would rise when I gave the word', NULL, '2026-11-06 22:43:10'),
(69, 'demo-nights', 'The Nights — Luyện nghe qua bài hát', 'Luyện phản xạ nghe với ca khúc The Nights của Avicii.', 'Âm nhạc', 'B1', 'youtube', 'https://www.youtube.com/watch?v=UtF6Jej8yb4', 'https://i.ytimg.com/vi/UtF6Jej8yb4/maxresdefault.jpg', 191, 20, 4, NULL, 'Hey, once upon a younger year When all our shadows disappeared The animals inside came out to play Hey, when face to face with all our fears', NULL, '2026-11-05 22:43:10'),
(70, 'demo-counting-stars', 'Counting Stars — Luyện nghe qua bài hát', 'Một bài luyện nghe dài hơn với ca từ quen thuộc của OneRepublic.', 'Âm nhạc', 'B2', 'youtube', 'https://www.youtube.com/watch?v=hT_nvWreIhg', 'https://i.ytimg.com/vi_webp/hT_nvWreIhg/maxresdefault.webp', 283, 30, 5, NULL, 'Lately Ive been Ive been losing sleep Dreaming about the things that we could be But baby Ive been Ive been praying hard Said no more counting dollars well be counting stars Yeah well be counting stars I see this life like a swinging vine Swing my heart across the line And in my face is flashing signs Seek it out and ye shall find Old but Im not that old Young but Im not that bold And I dont think the world is sold On just doing what were told I feel something so right Doing the wrong thing And ', NULL, '2026-11-04 22:43:10'),
(71, 'demo-personal-counting-stars', 'My Listening: Counting Stars', 'Video cá nhân của Minh Anh để luyện nghe lại bài hát yêu thích.', 'Video của tôi', 'B2', 'youtube', 'https://www.youtube.com/watch?v=hT_nvWreIhg', 'https://i.ytimg.com/vi_webp/hT_nvWreIhg/maxresdefault.webp', 283, 0, 0, 817, 'Lately Ive been Ive been losing sleep Dreaming about the things that we could be But baby Ive been Ive been praying hard Said no more counting dollars well be counting stars Yeah well be counting stars I see this life like a swinging vine Swing my heart across the line And in my face is flashing signs Seek it out and ye shall find Old but Im not that old Young but Im not that bold And I dont think the world is sold On just doing what were told I feel something so right Doing the wrong thing And ', NULL, '2026-11-16 22:43:10');
