INSERT INTO `video_segments` (`id`, `video_id`, `start_ms`, `end_ms`, `text_en`, `text_vi`, `sort_order`) VALUES
(1341, 66, 12400, 14880, 'So whats new mark', NULL, 1),
(1342, 66, 14880, 19279, 'How is your new job going to be honest', NULL, 2),
(1343, 66, 19279, 21520, 'I cant complain', NULL, 3),
(1344, 66, 21520, 26080, 'I really love the company that I am working for', NULL, 4),
(1345, 66, 26080, 30640, 'My co workers are all really friendly and helpful', NULL, 5),
(1346, 66, 30640, 34000, 'They really help me feel welcome', NULL, 6),
(1347, 66, 34000, 38239, 'Its a really energetic and fun atmosphere', NULL, 7),
(1348, 66, 38239, 41040, 'My boss is hilarious', NULL, 8),
(1349, 66, 41040, 43600, 'And hes really flexible', NULL, 9),
(1350, 66, 43600, 47600, 'Really how so', NULL, 10),
(1351, 66, 47600, 53760, 'He allows me to come in when I want and make my own hours', NULL, 11),
(1352, 66, 53760, 57760, 'I can also leave early if I start early', NULL, 12),
(1353, 66, 57760, 60960, 'There is no real dress code either', NULL, 13),
(1354, 66, 60960, 68400, 'I can wear jeans and a t shirt if I want I can even wear shorts in the summer', NULL, 14),
(1355, 66, 68400, 72400, 'Wow it sounds really cool', NULL, 15),
(1356, 66, 72400, 76479, 'I cant stand wearing a suit every day', NULL, 16),
(1357, 66, 76479, 81840, 'Which do you prefer working late or finishing early', NULL, 17),
(1358, 66, 81840, 84560, 'I prefer finishing early', NULL, 18),
(1359, 66, 84560, 91600, 'I really enjoy the morning I love getting up early and going for a run', NULL, 19),
(1360, 66, 91600, 97680, 'Theres nothing like watching the sunrise while drinking my morning coffee', NULL, 20),
(1361, 66, 97680, 101680, 'Really I am opposite', NULL, 21),
(1362, 66, 101680, 104720, 'I love sleeping in', NULL, 22),
(1363, 66, 104720, 114159, 'I am most alert in the evenings Im a real night owl', NULL, 23),
(1364, 66, 114159, 116960, 'Well you know what they say', NULL, 24),
(1365, 66, 116960, 120000, 'The early bird catches the worm', NULL, 25),
(1366, 66, 120000, 122880, 'You know you could be right', NULL, 26),
(1367, 66, 122880, 129840, 'Maybe I will try to go to bed a little earlier tonight', NULL, 27),
(1369, 67, 5450, 7429, 'How was your trip', NULL, 1),
(1371, 67, 7429, 9889, 'It was really fun', NULL, 2),
(1373, 67, 9889, 12440, 'How was the weather', NULL, 3),
(1375, 67, 12440, 17660, 'The weather was beautiful it was warm and sunny every day', NULL, 4),
(1377, 67, 17660, 20029, 'How were the people', NULL, 5),
(1379, 67, 20029, 24840, 'The people were very friendly and helpful what did you do', NULL, 6),
(1381, 67, 24840, 26730, 'I had some meetings', NULL, 7),
(1383, 67, 26730, 30470, 'I ate at some delicious restaurants and I did some sightseeing', NULL, 8),
(1385, 67, 30470, 32899, 'How was the hotel', NULL, 9),
(1387, 67, 32899, 35460, 'The hotel was very nice', NULL, 10),
(1389, 67, 35460, 38520, 'The service was great I see', NULL, 11),
(1391, 67, 38520, 40879, 'How was the food', NULL, 12),
(1393, 67, 40879, 43530, 'The food was amazing', NULL, 13),
(1395, 67, 43530, 47039, 'I ate many different kinds of food was it expensive', NULL, 14),
(1397, 67, 47039, 50250, 'I think it was reasonable', NULL, 15),
(1399, 67, 50250, 52440, 'I didnt spend too much money', NULL, 16),
(1401, 67, 52440, 55890, 'Sounds like you had a wonderful vacation', NULL, 17),
(1403, 67, 55890, 59160, 'Yes just one bad thing happened', NULL, 18),
(1405, 67, 59160, 61050, 'Really what happened', NULL, 19),
(1407, 67, 61050, 64430, 'I got sick I got food poisoning', NULL, 20),
(1409, 67, 64430, 71390, 'Wow thats awful I thought you said the food was delicious', NULL, 21),
