(1415, 68, 16697, 19920, 'Seas would rise when I gave the word', NULL, 2),
(1417, 68, 20000, 24260, 'Now in the morning I sleep alone', NULL, 3),
(1419, 68, 24260, 28390, 'Sweep the streets I used to own', NULL, 4),
(1421, 68, 40920, 43901, 'I used to roll the dice', NULL, 5),
(1423, 68, 43901, 48000, 'Feel the fear in my enemys eyes', NULL, 6),
(1425, 68, 48440, 51303, 'Listened as the crowd would sing', NULL, 7),
(1427, 68, 51303, 55120, 'Now the old king is dead long live the king', NULL, 8),
(1429, 68, 55320, 58264, 'One minute I held the key', NULL, 9),
(1431, 68, 58264, 62000, 'Next the walls were closed on me', NULL, 10),
(1433, 68, 62200, 69290, 'And I discovered that my castles stand Upon pillars of salt and pillars of sand', NULL, 11),
