INSERT INTO `video_vocabulary` (`id`, `video_id`, `word`, `ipa`, `meaning_vi`, `detail_vi`, `sort_order`) VALUES
(136, 66, 'coworker', '/ˈkoʊˌwɜːrkər/', 'đồng nghiệp', 'Người cùng làm việc trong một công ty. "My coworkers are really friendly."', 1),
(137, 66, 'friendly', '/ˈfrendli/', 'thân thiện', 'Dễ gần và tốt với người khác. "Everyone here is friendly and helpful."', 2),
(138, 66, 'helpful', '/ˈhelpfl/', 'hay giúp đỡ', 'Sẵn sàng giúp người khác khi cần. "They help me feel welcome."', 3),
(139, 66, 'atmosphere', '/ˈætməsfɪr/', 'bầu không khí', 'Cảm giác chung của một nơi làm việc. "It has an energetic atmosphere."', 4),
(140, 66, 'hilarious', '/hɪˈleriəs/', 'rất buồn cười', 'Cực kỳ hài hước. "My boss is hilarious."', 5),
(141, 66, 'flexible', '/ˈfleksəbl/', 'linh hoạt', 'Có thể thay đổi giờ giấc cho phù hợp. "He is really flexible about hours."', 6),
(142, 66, 'dress code', '/ˈdres koʊd/', 'quy định trang phục', 'Quy tắc về quần áo khi đến nơi làm việc. "There is no real dress code."', 7),
(143, 66, 'sunrise', '/ˈsʌnraɪz/', 'bình minh', 'Lúc mặt trời mọc. "I love watching the sunrise with my coffee."', 8),
(144, 66, 'mood', '/muːd/', 'tâm trạng', 'Trạng thái cảm xúc của một người. "He is in a good mood."', 9),
(145, 67, 'trip', '/trɪp/', 'chuyến đi', 'Một chuyến đi ngắn hoặc chuyến du lịch. "How was your trip?"', 1),
(146, 67, 'weather', '/ˈweðər/', 'thời tiết', 'Tình trạng khí hậu trong một ngày. "The weather was beautiful."', 2),
(147, 67, 'sunny', '/ˈsʌni/', 'nắng', 'Có nhiều ánh nắng mặt trời. "It was warm and sunny every day."', 3),
(148, 67, 'sightseeing', '/ˈsaɪtsiːɪŋ/', 'đi tham quan', 'Đi thăm những điểm nổi tiếng. "I did some sightseeing."', 4),
(149, 67, 'delicious', '/dɪˈlɪʃəs/', 'ngon', 'Có vị rất ngon. "I ate at some delicious restaurants."', 5),
(150, 67, 'reasonable', '/ˈriːznəbl/', 'hợp lý (giá cả)', 'Không quá đắt. "I think the price was reasonable."', 6),
(151, 67, 'vacation', '/veɪˈkeɪʃn/', 'kỳ nghỉ', 'Thời gian nghỉ để đi du lịch. "You had a wonderful vacation."', 7),
(152, 67, 'food poisoning', '/fuːd ˈpɔɪzənɪŋ/', 'ngộ độc thực phẩm', 'Bị bệnh sau khi ăn thức ăn không an toàn. "I got food poisoning."', 8),
(153, 68, 'rule', '/ruːl/', 'cai trị; quy tắc', 'Điều khiển hoặc quản lý. "I used to rule the world."', 1),
(154, 68, 'rise', '/raɪz/', 'dâng lên', 'Đi lên hoặc tăng lên. "Seas would rise when I gave the word."', 2),
(155, 68, 'sweep', '/swiːp/', 'quét', 'Làm sạch bằng chổi. "Sweep the streets I used to own."', 3),
(156, 68, 'own', '/oʊn/', 'sở hữu', 'Có thứ gì đó thuộc về mình. "The streets I used to own."', 4),
(157, 68, 'world', '/wɜːrld/', 'thế giới', 'Toàn bộ hành tinh hoặc mọi người. "I used to rule the world."', 5),
(158, 68, 'sleep', '/sliːp/', 'ngủ', 'Nghỉ ngơi với mắt nhắm. "Now in the morning I sleep alone."', 6),
(159, 68, 'word', '/wɜːrd/', 'lời nói', 'Một đơn vị ngôn ngữ. "When I gave the word."', 7),
(160, 68, 'morning', '/ˈmɔːrnɪŋ/', 'buổi sáng', 'Phần đầu của ngày. "Now in the morning I sleep alone."', 8),
(161, 69, 'shadow', '/ˈʃædoʊ/', 'bóng tối', 'Vùng tối do vật cản ánh sáng. "When all our shadows disappeared."', 1),
(162, 69, 'disappear', '/ˌdɪsəˈpɪr/', 'biến mất', 'Không còn nhìn thấy nữa. "All our shadows disappeared."', 2),
(163, 69, 'fear', '/fɪr/', 'nỗi sợ', 'Cảm giác lo lắng trước nguy hiểm. "Face to face with all our fears."', 3),
(164, 69, 'tear', '/tɪr/', 'nước mắt', 'Giọt nước từ mắt khi khóc. "We learned our lessons through the tears."', 4),
(165, 69, 'memory', '/ˈmeməri/', 'kỷ niệm', 'Điều còn nhớ về quá khứ. "Made memories we knew would never fade."', 5),
(166, 69, 'dream', '/driːm/', 'giấc mơ', 'Hình ảnh trong khi ngủ hoặc điều mong ước. "Dreaming about the things we could be."', 6),
(167, 69, 'lesson', '/ˈlesn/', 'bài học', 'Điều học được từ trải nghiệm. "We learned our lessons through the tears."', 7),
(168, 69, 'play', '/pleɪ/', 'vui chơi', 'Làm điều gì đó để giải trí. "The animals inside came out to play."', 8),
(169, 70, 'lose sleep', '/luːz sliːp/', 'mất ngủ', 'Không ngủ được vì lo nghĩ. "I have been losing sleep."', 1),
(170, 70, 'dream', '/driːm/', 'mơ ước', 'Nghĩ về điều mình mong muốn. "Dreaming about the things that we could be."', 2),
(171, 70, 'pray', '/preɪ/', 'cầu nguyện', 'Nói chuyện với thần linh hoặc cầu mong điều tốt. "I have been praying hard."', 3),
(172, 70, 'count', '/kaʊnt/', 'đếm', 'Xác định số lượng. "We will be counting stars."', 4),
(173, 70, 'swing', '/swɪŋ/', 'đu đưa', 'Chuyển động qua lại. "Life is like a swinging vine."', 5),
(174, 70, 'vine', '/vaɪn/', 'dây leo', 'Cây leo có thân dài. "A swinging vine."', 6),
(175, 70, 'bold', '/boʊld/', 'tự tin, táo bạo', 'Dám làm điều khó. "Young but I am not that bold."', 7),
(176, 70, 'alive', '/əˈlaɪv/', 'còn sống, sống động', 'Cảm thấy tràn đầy sức sống. "Everything that kills me makes me feel alive."', 8),
