INSERT INTO `translations` (`id`, `user_id`, `file_name`, `original_text`, `source_language`, `translated_text`, `target_language`, `provider`, `created_at`) VALUES
(389, 817, 'notes.txt', 'Good morning! How are you today?', 'en', 'Chào buổi sáng! Hôm nay bạn thế nào?', 'vi', 'demo', '2026-11-18 22:43:10'),
(390, 818, NULL, 'I would like a coffee and a croissant, please.', 'en', 'Tôi muốn một ly cà phê và một chiếc bánh sừng bò.', 'vi', 'demo', '2026-11-17 22:43:10'),
(391, 819, NULL, 'The meeting has been moved to Friday afternoon.', 'en', 'Cuộc họp đã được dời sang chiều thứ Sáu.', 'vi', 'demo', '2026-11-16 22:43:10'),
(392, 820, 'notes.txt', 'Could you help me find the nearest train station?', 'en', 'Bạn có thể giúp tôi tìm ga tàu gần nhất không?', 'vi', 'demo', '2026-11-15 22:43:10'),
(393, 821, NULL, 'Learning a little every day is better than cramming.', 'en', 'Học một chút mỗi ngày tốt hơn là học nhồi.', 'vi', 'demo', '2026-11-14 22:43:10'),
(394, 822, NULL, 'Can I have the bill, please?', 'en', 'Cho tôi xin hóa đơn được không?', 'vi', 'demo', '2026-11-13 22:43:10'),
(395, 823, 'notes.txt', 'I am looking forward to the weekend.', 'en', 'Tôi đang mong đến cuối tuần.', 'vi', 'demo', '2026-11-12 22:43:10'),
(396, 824, NULL, 'This neighborhood is quiet and family-friendly.', 'en', 'Khu này yên tĩnh và phù hợp với gia đình.', 'vi', 'demo', '2026-11-11 22:43:10'),
(397, 817, NULL, 'She has been studying English for three years.', 'en', 'Cô ấy đã học tiếng Anh được ba năm.', 'vi', 'demo', '2026-11-10 22:43:10'),
(398, 818, 'notes.txt', 'Could you repeat that more slowly?', 'en', 'Bạn có thể lặp lại chậm hơn không?', 'vi', 'demo', '2026-11-09 22:43:10'),
